 "content": "from collections import deque


def transform(grid):
    """Fill the interiors of rectangular colored frames with color 2."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 9 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            top = min(y for y, _ in cells)
            bottom = max(y for y, _ in cells)
            left = min(x for _, x in cells)
            right = max(x for _, x in cells)
            if bottom - top < 2 or right - left < 2:
                continue
            if all(grid[top][x] == color and grid[bottom][x] == color for x in range(left, right + 1)) and all(grid[y][left] == color and grid[y][right] == color for y in range(top, bottom + 1)):
                for y in range(top + 1, bottom):
                    for x in range(left + 1, right):
                        if grid[y][x] == 9:
                            out[y][x] = 2
    return out

if __name__ == '__main__':
    pass
